--
-- Name: block_webhook_destination_delete_if_published_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.block_webhook_destination_delete_if_published_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  referencing_routine_names TEXT[];
BEGIN
  SELECT ARRAY_AGG(DISTINCT d.name ORDER BY d.name)
  INTO referencing_routine_names
  FROM routine_completion_export ce
  JOIN routine_definition d ON d.id = ce.definition_id
  JOIN agents a ON a.id = d.agent_id
  WHERE a.workspace_id = OLD.workspace_id
    AND d.status = 'published'
    AND ce.enabled = TRUE
    AND lower(ce.destination_ref) = OLD.id::text;

  IF COALESCE(array_length(referencing_routine_names, 1), 0) > 0 THEN
    RAISE EXCEPTION 'webhook destination % is referenced by published routines: %', OLD.id, array_to_string(referencing_routine_names, ', ')
      USING ERRCODE = '23503',
            CONSTRAINT = 'workspace_webhook_destinations_published_routine_reference';
  END IF;

  RETURN OLD;
END;
$$;


--
-- Name: enforce_agent_skill_target_reference(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_agent_skill_target_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_uuid UUID;
  target_exists BOOLEAN;
BEGIN
  IF NEW.kind = 'external_mcp' THEN
    IF NEW.target_type IS DISTINCT FROM 'mcp_connection' OR NEW.target_id IS NULL THEN
      RAISE EXCEPTION 'external_mcp skill % must target an MCP connection', NEW.id
        USING ERRCODE = '23503',
              CONSTRAINT = 'agent_skills_external_mcp_target_fk';
    END IF;
    target_uuid := agent_skill_target_uuid(NEW.target_id, 'mcp_connection');
    SELECT TRUE INTO target_exists
    FROM mcp_connections
    WHERE id = target_uuid
      AND agent_id = NEW.agent_id
    FOR KEY SHARE;
    IF target_exists IS NOT TRUE THEN
      RAISE EXCEPTION 'external_mcp skill % references unknown MCP connection %', NEW.id, NEW.target_id
        USING ERRCODE = '23503',
              CONSTRAINT = 'agent_skills_external_mcp_target_fk';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.kind = 'customer_email' THEN
    IF NEW.target_type IS DISTINCT FROM 'customer_email_connection' OR NEW.target_id IS NULL THEN
      RAISE EXCEPTION 'customer_email skill % must target a customer email connection', NEW.id
        USING ERRCODE = '23503',
              CONSTRAINT = 'agent_skills_customer_email_target_fk';
    END IF;
    target_uuid := agent_skill_target_uuid(NEW.target_id, 'customer_email_connection');
    SELECT TRUE INTO target_exists
    FROM integration_connections
    WHERE id = target_uuid
      AND workspace_id = NEW.workspace_id
      AND provider IN ('customer_email_google', 'customer_email_microsoft')
    FOR KEY SHARE;
    IF target_exists IS NOT TRUE THEN
      RAISE EXCEPTION 'customer_email skill % references unknown customer email connection %', NEW.id, NEW.target_id
        USING ERRCODE = '23503',
              CONSTRAINT = 'agent_skills_customer_email_target_fk';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.kind = 'webhook' THEN
    IF NEW.target_type IS DISTINCT FROM 'webhook_destination' OR NEW.target_id IS NULL THEN
      RAISE EXCEPTION 'webhook skill % must target a webhook destination', NEW.id
        USING ERRCODE = '23503',
              CONSTRAINT = 'agent_skills_webhook_target_fk';
    END IF;
    target_uuid := agent_skill_target_uuid(NEW.target_id, 'webhook_destination');
    SELECT TRUE INTO target_exists
    FROM workspace_webhook_destinations
    WHERE id = target_uuid
      AND workspace_id = NEW.workspace_id
    FOR KEY SHARE;
    IF target_exists IS NOT TRUE THEN
      RAISE EXCEPTION 'webhook skill % references unknown webhook destination %', NEW.id, NEW.target_id
        USING ERRCODE = '23503',
              CONSTRAINT = 'agent_skills_webhook_target_fk';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.kind = 'slack' THEN
    IF NEW.target_type IS DISTINCT FROM 'slack_installation' OR NEW.target_id IS NULL THEN
      RAISE EXCEPTION 'slack skill % must target a Slack installation', NEW.id
        USING ERRCODE = '23503',
              CONSTRAINT = 'agent_skills_slack_target_fk';
    END IF;
    target_uuid := agent_skill_target_uuid(NEW.target_id, 'slack_installation');
    SELECT TRUE INTO target_exists
    FROM slack_installations
    WHERE id = target_uuid
      AND workspace_id = NEW.workspace_id
    FOR KEY SHARE;
    IF target_exists IS NOT TRUE THEN
      RAISE EXCEPTION 'slack skill % references unknown Slack installation %', NEW.id, NEW.target_id
        USING ERRCODE = '23503',
              CONSTRAINT = 'agent_skills_slack_target_fk';
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: enforce_published_routine_completion_export_destination(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_published_routine_completion_export_destination() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  definition_workspace_id UUID;
  definition_status TEXT;
  destination_exists BOOLEAN;
BEGIN
  IF NEW.enabled IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  SELECT a.workspace_id, d.status
  INTO definition_workspace_id, definition_status
  FROM routine_definition d
  JOIN agents a ON a.id = d.agent_id
  WHERE d.id = NEW.definition_id;

  IF definition_status IS DISTINCT FROM 'published' THEN
    RETURN NEW;
  END IF;

  SELECT TRUE
  INTO destination_exists
  FROM workspace_webhook_destinations destination
  WHERE destination.workspace_id = definition_workspace_id
    AND destination.id::text = lower(NEW.destination_ref)
  FOR KEY SHARE;

  IF destination_exists IS NOT TRUE THEN
    RAISE EXCEPTION 'published routine completion export references unknown webhook destination %', NEW.destination_ref
      USING ERRCODE = '23503',
            CONSTRAINT = 'routine_completion_export_destination_ref_published_fk';
  END IF;

  RETURN NEW;
END;
$$;


