-- Name: retrieval_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.retrieval_settings (
    chunking_strategy text DEFAULT 'fixed_window'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    workspace_id uuid NOT NULL,
    chat_provider text,
    chat_model text,
    rewrite_provider text,
    rewrite_model text,
    rerank_provider text,
    rerank_model text,
    CONSTRAINT retrieval_settings_chat_capability_pair CHECK ((((chat_provider IS NULL) AND (chat_model IS NULL)) OR ((chat_provider IS NOT NULL) AND (chat_model IS NOT NULL)))),
    CONSTRAINT retrieval_settings_chat_provider_check CHECK (((chat_provider IS NULL) OR (chat_provider = ANY (ARRAY['openai'::text, 'openai-compatible'::text, 'gemini'::text, 'claude'::text])))),
    CONSTRAINT retrieval_settings_rerank_capability_pair CHECK ((((rerank_provider IS NULL) AND (rerank_model IS NULL)) OR ((rerank_provider IS NOT NULL) AND (rerank_model IS NOT NULL)))),
    CONSTRAINT retrieval_settings_rerank_provider_check CHECK (((rerank_provider IS NULL) OR (rerank_provider = ANY (ARRAY['openai'::text, 'openai-compatible'::text, 'gemini'::text, 'claude'::text])))),
    CONSTRAINT retrieval_settings_rewrite_capability_pair CHECK ((((rewrite_provider IS NULL) AND (rewrite_model IS NULL)) OR ((rewrite_provider IS NOT NULL) AND (rewrite_model IS NOT NULL)))),
    CONSTRAINT retrieval_settings_rewrite_provider_check CHECK (((rewrite_provider IS NULL) OR (rewrite_provider = ANY (ARRAY['openai'::text, 'openai-compatible'::text, 'gemini'::text, 'claude'::text]))))
);


