--

CREATE TABLE public.routine_step (
    definition_id uuid NOT NULL,
    stable_step_id text NOT NULL,
    kind text NOT NULL,
    instruction text NOT NULL,
    tool_ref text,
    ordinal integer NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    action_type text,
    capture_key text,
    options jsonb,
    CONSTRAINT routine_step_instruction_check CHECK ((NULLIF(btrim(instruction), ''::text) IS NOT NULL)),
    CONSTRAINT routine_step_kind_check CHECK ((kind = ANY (ARRAY['chat'::text, 'tool'::text, 'action'::text, 'approval'::text]))),
    CONSTRAINT routine_step_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT routine_step_stable_step_id_check CHECK ((NULLIF(btrim(stable_step_id), ''::text) IS NOT NULL))
);


--
-- Name: routine_terminal; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.routine_terminal (
    definition_id uuid NOT NULL,
    stable_step_id text NOT NULL,
    kind text NOT NULL,
    instruction text,
    action_type text,
    ordinal integer NOT NULL,
    CONSTRAINT routine_terminal_check CHECK ((((kind = 'action'::text) AND (NULLIF(btrim(action_type), ''::text) IS NOT NULL)) OR (kind <> 'action'::text))),
    CONSTRAINT routine_terminal_kind_check CHECK ((kind = ANY (ARRAY['complete'::text, 'handoff'::text]))),
    CONSTRAINT routine_terminal_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT routine_terminal_stable_step_id_check CHECK ((NULLIF(btrim(stable_step_id), ''::text) IS NOT NULL))
);


--
-- Name: routine_transition; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.routine_transition (
    definition_id uuid NOT NULL,
    from_step text NOT NULL,
    to_ref text NOT NULL,
    guard_kind text NOT NULL,
    guard_text text,
    ordinal integer NOT NULL,
    outcome_status text,
    counter_limit integer,
    field_ref text,
    field_op text,
    field_value jsonb,
    field_values jsonb,
    field_unit text,
    CONSTRAINT routine_transition_counter_limit_check CHECK (((counter_limit IS NULL) OR (counter_limit > 0))),
    CONSTRAINT routine_transition_from_step_check CHECK ((NULLIF(btrim(from_step), ''::text) IS NOT NULL)),
    CONSTRAINT routine_transition_guard_kind_check CHECK ((guard_kind = ANY (ARRAY['llm'::text, 'default'::text, 'slot_filled'::text, 'outcome'::text, 'counter'::text, 'field'::text]))),
    CONSTRAINT routine_transition_ordinal_check CHECK ((ordinal >= 0)),
    CONSTRAINT routine_transition_to_ref_check CHECK ((NULLIF(btrim(to_ref), ''::text) IS NOT NULL))
);


